var o=[{title:`Os movimentos da anca`,text:`A flexão da anca aproxima a coxa do tronco, e a extensão leva-a para trás. A articulação também roda para dentro e para fora e move a perna para o outro lado ou para longe do corpo. Os movimentos do dia a dia combinam várias direções, por isso tocar nos dedos dos pés à frente conta-lhe apenas parte da história.`},{title:`Exercícios para experimentar`,text:`Um alongamento confortável do flexor da anca em meio-ajoelhado explora a extensão enquanto mantém a pélvis controlada. As rotações suaves da anca em 90/90 ou os exercícios de rotação sentado praticam a rotação, e um afundo lateral apoiado explora o comprimento e o controlo da parte interna da coxa (adutores). Comece devagar e agarre-se a um apoio se o equilíbrio parecer instável.`},{title:`As ancas nos seus levantamentos`,text:`Os agachamentos precisam que as ancas e os tornozelos se movam em conjunto. As dobras de anca precisam de flexão da anca com um tronco controlado. Num split squat, uma anca estende-se enquanto a outra dobra. Se um agachamento profundo for desconfortável, uma posição diferente, uma profundidade menor, um apoio sob os calcanhares ou agachar até uma cadeira podem resolver mais depressa do que forçar um alongamento.`},{title:`As ancas de cada pessoa são diferentes`,text:`A forma da cavidade da anca, o historial de treino, a força atual e a tolerância articular afetam todos a sua amplitude. Uma assimetria não é automaticamente um defeito, e o mesmo alongamento não pertence a todos os planos. Pare qualquer exercício que cause beliscão, dor articular aguda ou sintomas que persistam e consulte um médico ou fisioterapeuta quando necessário.`},{title:`Acompanhar o progresso`,text:`Faça alguns exercícios de anca focados antes das sessões em que um movimento beneficie deles. Meça o progresso pela confiança e fluidez dos seus agachamentos, dobras de anca e afundos e deixe de lado a profundidade máxima do alongamento.`}];var s=[{label:`ACE 2026: mobilidade versus flexibilidade`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};